def decrypt(short_arr, offset, length, xor_key):
    """Decrypt using the XOR algorithm: char[i] = short[offset+i] ^ xor_key"""
    result = []
    for i in range(length):
        if offset + i >= len(short_arr):
            break
        val = short_arr[offset + i] ^ xor_key
        # Handle Java short (16-bit signed) - convert to unsigned for XOR
        if val < 0:
            val = val + 65536
        result.append(chr(val))
    return ''.join(result)


def try_decrypt_range(short_arr, offset, xor_key, max_len=50):
    """Try decrypting with different lengths to find valid strings"""
    results = []
    for length in range(1, min(max_len + 1, len(short_arr) - offset + 1)):
        s = decrypt(short_arr, offset, length, xor_key)
        # Check if all characters are printable ASCII or common Unicode
        if all(32 <= ord(c) <= 126 or ord(c) > 127 for c in s):
            results.append((length, s))
    return results


def to_unsigned_short(val):
    """Convert Java signed short to unsigned"""
    if val < 0:
        return val + 65536
    return val


